export const MAX_CELLS = 10000;

export function makeGrid(extent, cell) {
  const cols = Math.ceil((extent.maxX - extent.minX) / cell);
  const rows = Math.ceil((extent.maxY - extent.minY) / cell);
  if (cols * rows > MAX_CELLS) throw new Error('The grid would have more than ' + MAX_CELLS + ' cells');
  const cells = [];
  for (let r = 0; r < rows; r += 1) {
    for (let k = 0; k < cols; k += 1) {
      cells.push({ x: extent.minX + k * cell, y: extent.maxY - (r + 1) * cell, size: cell });
    }
  }
  return { cols, rows, cells };
}

