import { makeGrid } from './grid.js';

// Gridded Reference Graphic over the active layer's extent, in metres.
export function referenceGraphic(layer, options = {}) {
  const cell = options.cell ?? 100;
  const grid = makeGrid(layer.extentMetres, cell);
  return grid.cells.map((cellBox, i) => ({ ...cellBox, label: labelOf(i, grid.cols) }));
}

function labelOf(i, cols) {
  return String.fromCharCode(65 + (Math.floor(i / cols) % 26)) + ((i % cols) + 1);
}
